namespace Jsonata.Net.Core.Parsing; public readonly struct Token {     public TokenType Type { get; }     public string Value { get; }     public int Position { get; }     public Token(TokenType type, string value, int position) {         this.Type = type; this.Value = value; this.Position = position;     }     public override string ToString() => $"{Type}: '{Value}' @ {Position}"; }
